    ; load for cleanup
    LDA _got
    LDX _got+1
    ; scope-exit release
    LDY #$00
    JSR _obj_decref
    ; load for cleanup
    LDA _v1
    LDX _v1+1
    ; scope-exit release
    LDY #$00
    JSR _obj_decref
    ; load for cleanup
    LDA _k1
    LDX _k1+1
    ; scope-exit release
    LDY #$00
    JSR _obj_decref
    ; load for cleanup
    LDA _miss
    LDX _miss+1
    ; scope-exit release
    LDY #$00
    JSR _obj_decref
    ; load for cleanup
    LDA _probe
    LDX _probe+1
    ; scope-exit release
    LDY #$00
    JSR _obj_decref
    ; load for cleanup
    LDA _m
    LDX _m+1
    ; scope-exit release
    LDY #$00
    JSR _obj_decref
    RTS
    ; === end main ===

